INSERT INTO public.platform_changelog (title, description, category, area) VALUES
('Datas de expiração das bases PDA na Sinaleira', 'Agora a Sinaleira PDA mostra a data de expiração de cada base direto na tabela, puxando do endpoint GetBasesByUser. Fica mais fácil enxergar quem está perto de vencer e agir antes.', 'novidade', 'Customer Success'),
('Cache inteligente das chamadas PDA', 'Criamos uma camada de cache em Postgres para as chamadas ao PDA: lista de bases e datas de expiração ficam 6h em cache, saldo de créditos 1h e movimentações 30min. Reduz drasticamente o volume de chamadas — atendendo o pedido do time da PDA pra economizar a API. O botão Atualizar respeita o cache; o novo botão Forçar busca direto na API quando precisar de dado fresquinho.', 'melhoria', 'PDA'),
('Stale-on-error nas chamadas PDA', 'Se a API da PDA cair ou retornar erro, a Sinaleira passa a mostrar o último dado em cache em vez de quebrar a tela. Mais resiliência no dia a dia.', 'melhoria', 'PDA'),
('Liberação manual dos Dilemas por turma', 'O admin da Academy agora controla, por turma, quando os Dilemas ficam liberados para os alunos.', 'novidade', 'Academy'),
('Busca de empresas e contatos mais rápida', 'Adicionamos índices em cs_companies e cs_contacts (busca por nome e email sem diferenciar maiúsculas). As telas de CS carregam e filtram bem mais rápido.', 'melhoria', 'Customer Success'),
('Plataforma com 267 colaboradores ativos', 'Fechamos a semana com 267 perfis cadastrados na plataforma — sendo 5 novos colaboradores que entraram nos últimos 7 dias. Bem-vindos! 🎉', 'novidade', 'Plataforma');